package com.payshield.api; import com.payshield.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/payments") public class PaymentController {private final PaymentService service;public PaymentController(PaymentService s){service=s;} @PostMapping public ResponseEntity<PaymentResponse> create(@Valid @RequestBody PaymentRequest request,@RequestHeader(value="Idempotency-Key",required=false) String key){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request,key));} @GetMapping("/{id}") public PaymentResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping("/{id}/refunds") public PaymentResponse refund(@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false) String key){return service.refund(id,key);}@GetMapping("/{id}/ledger") public List<LedgerResponse> ledger(@PathVariable UUID id){return service.ledger(id);}}
